from review import card,save,DATE
id='TCS-1693';_,c=card(id)
refs=c['references']+[dict(id='strong2026',title='Optimal Mixing of Glauber Dynamics for the Sherrington–Kirkpatrick Model at β<1/2',authors='Sihan Wang',year=2026,url='https://arxiv.org/abs/2608.22159v2',locator='Version 2, 28 August 2026. Theorem 1.1 and Section 1.1 read, including the SK normalization and random-scan discrete-time convention. Claims a strong Poincaré inequality, a modified log-Sobolev inequality and worst-start mixing; this is a recent preprint, not an independently verified sharp-threshold theorem.')]
blocks=c['context_blocks']+[dict(title='A newer preprint gives stronger bounds below one half',text='Wang’s August 2026 preprint claims O_β(n log(n/ε)) random-scan Glauber steps to total variation error ε for every fixed β<1/2, with high probability over the Gaussian couplings and uniformly over external fields. It uses off-diagonal interactions of variance β²/n, matching the zero-field Gibbs normalization above. The claimed Poincaré and modified log-Sobolev constants have inverse rates Ω_β(1/n) per discrete update. A modified log-Sobolev inequality is not the ordinary LSI displayed above, and a result for β<1/2 does not identify the full temperature threshold.',citation='strong2026')]
